/**
 * Tests that the rpc scheduler is called when requests arrive.
 */
@Test
public void testRpcScheduler() throws IOException, InterruptedException {
    RpcScheduler scheduler = spy(new FifoRpcScheduler(CONF, 1));
    RpcServer rpcServer = new TestRpcServer(scheduler);
    verify(scheduler).init((RpcScheduler.Context) anyObject());
    AbstractRpcClient client = createRpcClient(CONF);
    try {
        rpcServer.start();
        verify(scheduler).start();
        MethodDescriptor md = SERVICE.getDescriptorForType().findMethodByName("echo");
        EchoRequestProto param = EchoRequestProto.newBuilder().setMessage("hello").build();
        for (int i = 0; i < 10; i++) {
            client.call(new PayloadCarryingRpcController(CellUtil.createCellScanner(ImmutableList.<Cell>of(CELL))), md, param, md.getOutputType().toProto(), User.getCurrent(), rpcServer.getListenerAddress(), new MetricsConnection.CallStats());
        }
        verify(scheduler, times(10)).dispatch((CallRunner) anyObject());
    } finally {
        rpcServer.stop();
        verify(scheduler).stop();
    }
}

