    try {
        Mapper<ImmutableBytesWritable, Result, Text, KeyValue>.Context ctx = mock(Mapper.Context.class);
        when(ctx.getConfiguration()).thenReturn(configuration);
        SweepMapper map = new SweepMapper();
        doAnswer(new Answer<Void>() {

            @Override
