        @Override
        public Void answer(InvocationOnMock invocation) throws Throwable {
            dataFromMembers.add(memberData);
            committed.countDown();
            return null;
        }
    }).when(coordinator).memberFinishedBarrier(Mockito.eq(operationName), Mockito.anyString(), Mockito.eq(memberData));
    return coordinator;
